250	  /**
251	   * Add the time to proxy an operation from the moment the Router sends it to
252	   * the Namenode until it replied.
253	   * @param time Proxy time of an operation in nanoseconds.
254	   */
255	  public void addProxyTime(long time) {
256	    proxy.add(time);
257	    proxyOp.incr();
258	  }
