270	  /**
271	   * Add the time to process a request in the Router from the time we receive
272	   * the call until we send it to the Namenode.
273	   * @param time Process time of an operation in nanoseconds.
274	   */
275	  public void addProcessingTime(long time) {
276	    processing.add(time);
277	    processingOp.incr();
278	  }
