1529	  /**
1530	   * Acquire permit to continue processing the request for specific nsId.
1531	   *
1532	   * @param nsId Identifier of the block pool.
1533	   * @param ugi UserGroupIdentifier associated with the user.
1534	   * @param m Remote method that needs to be invoked.
1535	   * @throws IOException If permit could not be acquired for the nsId.
1536	   */
1537	  private void acquirePermit(
1538	      final String nsId, final UserGroupInformation ugi, final RemoteMethod m)
1539	      throws IOException {
1540	    if (routerRpcFairnessPolicyController != null
1541	        && !routerRpcFairnessPolicyController.acquirePermit(nsId)) {
1542	      // Throw StandByException,
1543	      // Clients could fail over and try another router.
1544	      if (rpcMonitor != null) {
1545	        rpcMonitor.getRPCMetrics().incrProxyOpPermitRejected();
1546	      }
1547	      LOG.debug("Permit denied for ugi: {} for method: {}",
1548	          ugi, m.getMethodName());
1549	      String msg =
1550	          "Router " + router.getRouterId() +
1551	              " is overloaded for NS: " + nsId;
1552	      throw new StandbyException(msg);
1553	    }
1554	  }
1555	
1556	  /**
1557	   * Release permit for specific nsId after processing against downstream
1558	   * nsId is completed.
1559	   *
1560	   * @param nsId Identifier of the block pool.
1561	   * @param ugi UserGroupIdentifier associated with the user.
1562	   * @param m Remote method that needs to be invoked.
1563	   */
1564	  private void releasePermit(
1565	      final String nsId, final UserGroupInformation ugi, final RemoteMethod m) {
1566	    if (routerRpcFairnessPolicyController != null) {
1567	      routerRpcFairnessPolicyController.releasePermit(nsId);
1568	      LOG.trace("Permit released for ugi: {} for method: {}", ugi,
1569	          m.getMethodName());
1570	    }
1571	  }
